// Builds the host-admission bundle with EXACTLY scripts/build-host-admission.mjs's options, but writes only into the review
// dir: (1) from main's source -> compared with main's committed windows bundle (is it current?), (2) from the candidate.
import { build } from '/home/steven/Documents/Codex/2026-10-18/wo/work/enclave/node_modules/esbuild/lib/main.js';
import fs from 'node:fs/promises';
import { createHash } from 'node:crypto';
const R = '/home/steven/Documents/Codex/2026-10-18/wo/work/cron-startup-20261021/host-policy-review', E = '/home/steven/Documents/Codex/2026-10-18/wo/work/enclave';
