const opts = (entry) => ({ entryPoints: [entry], write: false, bundle: true, platform: 'node', format: 'esm', target: 'node20', minify: true,
  banner: { js: '// Generated by scripts/build-host-admission.mjs; edit network/host-admission-runtime.mjs.' } });
const committed = await fs.readFile(E + '/windows/node/host-admission.bundle.mjs');
const fromMain = (await build({ ...opts('network/host-admission-runtime.mjs'), absWorkingDir: E })).outputFiles[0].contents;
const fromCand = (await build({ ...opts('network/host-admission-runtime.mjs'), absWorkingDir: R + '/scratch' })).outputFiles[0].contents;
await fs.writeFile(R + '/candidate-bundle.mjs', fromCand);
console.log(JSON.stringify({ committed: sha(committed), rebuiltFromMain: sha(fromMain), mainBundleCurrent: Buffer.from(fromMain).equals(committed),
  candidateBundle: sha(fromCand), candidateBytes: fromCand.length }, null, 1));
